#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_xcipher;
float4 amzSample_xcipher(float2 uv) { return float4(amzt_xcipher.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xcipher(uv);return float4(0.0); }
uniform float amzp_AMOUNT;
uniform float amzp_autop;
uniform float amzp_PROGRESS;
uniform float amzp_SPEED;
uniform float amzp_ROTFEATHER;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float amzp_alpha;
uniform float amzp_GRADMAP;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_hardness;
uniform float amzp_THICKNESS;
uniform float amzp_DENSITY;
uniform float amzp_DIRECTION;
uniform float amzp_BRANCH;
uniform float amzp_SHADELENGTH;
uniform float amzp_SMOOTHLESS;
uniform float3 amzp_RAYORIGIN;
uniform float2 amzp_stretch;
uniform float amzp_blendMode;
uniform float amzp_overdrawOn;
    float4 newLayer( float4 a, float4 b) { return a * (1. - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s( float2 v ) { return (float4(v,0.,1.)*amzLayerToScreen()).xy; }
        float2x2 Rot(float a)
        {
            float s = sin(a), c = cos(a);
            return float2x2(c, -s, s, c);
        }
        float Feather(float2 uv)
        {
            float d = length(uv - float2(0, clamp(uv.y,-0.3, 0.3)));
            float r = mix(0.1, 0.01, smoothstep(-0.3, amzp_THICKNESS, uv.y));
            float m = smoothstep(0.01, 0.0, d - r);
            float side = sign(uv.x);
            float x = 0.9 * abs(uv.x) / r;
            float wave = (amzp_DENSITY -x) * sqrt(x) + (amzp_DIRECTION - sqrt(amzp_BRANCH - x)) * x;
            float y = (uv.y - wave * 0.2) * 80.0 + side;
            float id = floor(y + 20.0);
            float n = fract(sin(id * 650.2) * 795.0);
            float shade = mix(amzp_SHADELENGTH, 1.0, n);
            float strandLength = mix(amzp_SMOOTHLESS, 1.0, fract(n * 2.0));
            float strand = smoothstep(0.6, 0.0, abs(fract(y) - 0.5) - 0.3);
            strand *= smoothstep(0.3, 0.0, x - strandLength);
            d = length(uv - float2(0, clamp(uv.y,-0.45, 0.2)));
         float stem = smoothstep(0.01, 0.0, d + uv.y * 0.02);
            return max(strand*m*shade, stem);
        }
        float3 Transform(float3 p, float amzp_angle)
        {
            p.xz *= Rot(amzp_angle);
            p.xy *= Rot(amzp_angle * amzp_ROTFEATHER);
            return p;
        }
        float4 RayTracedFeather(float3 rayOrigin, float3 rayDirection, float3 amzp_position, float amzp_angle)
        {
            float4 col = float4(0);
            float t = dot(amzp_position - rayOrigin, rayDirection);
            float3 p = rayOrigin + rayDirection * t;
            float y = length(amzp_position - p);
            if (y < 1.0)
            {
             float x = sqrt(1.0 - y);
                float3 pF = rayOrigin + rayDirection * (t - x) - amzp_position;
                pF = Transform(pF, amzp_angle);
                float2 uvF = float2(atan(pF.x, pF.z), pF.y);
                uvF *= float2(0.25, 0.5);
                float f = Feather(uvF);
                float4 front = float4(float3(f), smoothstep(0.0, 0.1, f));
                float3 pB = rayOrigin + rayDirection * (t + x) - amzp_position;
                pB = Transform(pB, amzp_angle);
                float2 uvB = float2(atan(pB.x, pB.z), pB.y);
                uvB *= float2(0.25, 0.5);
                float b = Feather(uvB);
                float4 back = float4(float3(b), smoothstep(0.0, 0.1, b));
                col = mix(back, front, front.a);
            }
            return col;
        }
        void amzRender() {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float ovA = (amzp_overdrawOn>0.5) ? 1.0 : texColor.a;
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * ovA;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 iMouse = float2(0.5, 0.5);
        float T = (amzp_autop>0.5)? amzp_PROGRESS + (time*amzp_SPEED) : amzp_PROGRESS;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0-amzp_position.y))*float2(-1.0,1.0)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
            float2 uv = satriyaid;
            float2 M = iMouse.xy / iResolution.xy;
            float3 bg = float3(0.0, 0.0, 0.0);
            float4 col = float4(bg, 0);
            float3 rayOrigin = float3((amzp_RAYORIGIN.x*0.01), (amzp_RAYORIGIN.y*0.01), (amzp_RAYORIGIN.z*0.01));
            float3 rayDir = normalize(float3(uv, 1));
            for(float i= 0.0; i < 1.0; i+= 1.0/amzp_AMOUNT)
            {
                float x = mix(-8.0 , 8.0, fract(i + T*0.1)) + M.x * i * i;
                float y = mix(-2.0, 2.0,fract(sin(i * 324.5) * 7864.4)) + (M.y * i*i);
                float z = mix(5.0, 0.0, i);
                float a = T + i *530.35;
                float4 feather = RayTracedFeather(rayOrigin, rayDir, float3(x, y, z), a);
                feather.rg *= i;
                feather.b += i;
                feather.rgb = mix(bg.rgb, feather.rgb, mix(0.3, 1.0, i));
                feather.rgb = sqrt(feather.rgb);
                col = mix(col, feather, feather.a);
            }
            col = pow(col, float4(0.4545));
            fragColor = col;
         float4 factor = mix(texColorX,fragColor,1.0);
         const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float luminance = dot(fragColor.rgb, luminanceWeighting);
            float4 gradmap = mix(amzp_color1,amzp_color2,luminance)*fragColor.a;
         if((amzp_GRADMAP>0.5)) { factor = mix(texColorX,gradmap,1.0); }
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) { resultfinal = (factor * amzp_hardness) * ovA; }
          else if( int(amzp_blendMode)==1 ) { factor *= amzp_hardness;
            float4 c = factor + float4(1.0)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/max(texColor.a,0.0001))*c.rgb,1.0) * ovA; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.-((1.-(texColor.rgb/max(texColor.a,0.0001)))*(1.-factor.rgb)),1.0) * ovA; }
          else if( int(amzp_blendMode)==3 ) { factor *= amzp_hardness; resultfinal = newLayer(texColor, (factor*amzp_hardness)) * ovA; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
